async function run() {
  console.log(`Seeding ${courses.length} new courses...`);

  for (const { name, slug, description, icon, questions } of courses) {
    // Skip if already exists
    const existing = await db
      .select()
      .from(coursesTable)
      .where(eq(coursesTable.slug, slug))
      .limit(1);

    if (existing.length > 0) {
      console.log(`  SKIP (exists): ${name}`);
      continue;
    }

    const [course] = await db
      .insert(coursesTable)
      .values({ name, slug, description, icon })
      .returning();

    await db.insert(questionsTable).values(
      questions.map((q) => ({ ...q, courseId: course.id }))
    );

    const counts = { beginner: 0, intermediate: 0, advanced: 0 };
    for (const q of questions) counts[q.level]++;
    console.log(
      `  ✓ ${name} — ${counts.beginner}B / ${counts.intermediate}I / ${counts.advanced}A`
    );
  }

  console.log("\nDone! All courses seeded.");
  process.exit(0);
}

run().catch((err) => {
  console.error(err);
  process.exit(1);
});
